import adsk.core, adsk.fusion, json
def run(_context):
    app=adsk.core.Application.get(); out=[]
    for i in range(app.documents.count):
        doc=app.documents.item(i); des=adsk.fusion.Design.cast(doc.products.itemByProductType('DesignProductType'))
        if not des: continue
        root=des.rootComponent; rec={'i':i,'bodies':[b.name for b in root.bRepBodies],'sketches':[]}
        for sk in root.sketches:
            if sk.name not in ('CUT','CUT (1)'): continue
            a=[]
            for j in range(sk.profiles.count):
                pr=sk.profiles.item(j); bb=pr.boundingBox
                a.append({'j':j,'area':pr.areaProperties().area,'bb':[[bb.minPoint.x,bb.minPoint.y],[bb.maxPoint.x,bb.maxPoint.y]],'loops':[(pr.profileLoops.item(k).isOuter,pr.profileLoops.item(k).profileCurves.count) for k in range(pr.profileLoops.count)]})
            rec['sketches'].append({'name':sk.name,'profiles':a})
        out.append(rec)
    print(json.dumps(out))
